import React from "react";
import {
  Navigate,
  Route,
  Routes,
  Link,
  useLocation,
  useNavigate,
} from "react-router-dom";

import Login from "./components/Login";
import Register from "./components/Register";
import AccountDashboard from "./components/AccountDashboard";
import CreateAccountForm from "./components/CreateAccountForm";
import AccountDetails from "./components/AccountDetails";
import DepositForm from "./components/DepositForm";
import WithdrawForm from "./components/WithdrawForm";
import TransferForm from "./components/TransferForm";

import "./App.css";

// ================= PRIVATE ROUTE =================

function PrivateRoute({ children }) {
  const token = localStorage.getItem("token");

  if (!token) {
    return <Navigate to="/login" replace />;
  }

  return children;
}

// ================= LAYOUT =================

function Layout({ children }) {
  const navigate = useNavigate();
  const location = useLocation();

  const username = localStorage.getItem("username");
  const role = localStorage.getItem("role");

  const isAuthPage =
    location.pathname === "/login" ||
    location.pathname === "/register";

  const logout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("username");
    localStorage.removeItem("role");

    navigate("/login");
  };

  // Login/Register don't need the dashboard navbar
  if (isAuthPage) {
    return <>{children}</>;
  }

  return (
    <div className="app-shell">
      <header className="topbar">
        <Link to="/dashboard" className="logo">
          Bank<span>Flow</span>
        </Link>

        <nav>
          <Link to="/dashboard">
            Accounts
          </Link>

          {username && (
            <span className="user-pill">
              {username}
              {role ? ` · ${role}` : ""}
            </span>
          )}

          <button
            type="button"
            className="logout"
            onClick={logout}
          >
            Logout
          </button>
        </nav>
      </header>

      <main>{children}</main>
    </div>
  );
}

// ================= APP =================

function App() {
  const token = localStorage.getItem("token");

  return (
    <Routes>

      {/* HOME */}
      <Route
        path="/"
        element={
          <Navigate
            to={token ? "/dashboard" : "/login"}
            replace
          />
        }
      />

      {/* LOGIN */}
      <Route
        path="/login"
        element={
          <Layout>
            <Login />
          </Layout>
        }
      />

      {/* REGISTER */}
      <Route
        path="/register"
        element={
          <Layout>
            <Register />
          </Layout>
        }
      />

      {/* DASHBOARD */}
      <Route
        path="/dashboard"
        element={
          <PrivateRoute>
            <Layout>
              <AccountDashboard />
            </Layout>
          </PrivateRoute>
        }
      />

      {/* CREATE ACCOUNT */}
      <Route
        path="/accounts/new"
        element={
          <PrivateRoute>
            <Layout>
              <CreateAccountForm />
            </Layout>
          </PrivateRoute>
        }
      />

      {/* ACCOUNT DETAILS */}
      <Route
        path="/accounts/:accountId"
        element={
          <PrivateRoute>
            <Layout>
              <AccountDetails />
            </Layout>
          </PrivateRoute>
        }
      />

      {/* DEPOSIT */}
      <Route
        path="/accounts/:accountId/deposit"
        element={
          <PrivateRoute>
            <Layout>
              <DepositForm />
            </Layout>
          </PrivateRoute>
        }
      />

      {/* WITHDRAW */}
      <Route
        path="/accounts/:accountId/withdraw"
        element={
          <PrivateRoute>
            <Layout>
              <WithdrawForm />
            </Layout>
          </PrivateRoute>
        }
      />

      {/* TRANSFER */}
      <Route
        path="/accounts/:accountId/transfer"
        element={
          <PrivateRoute>
            <Layout>
              <TransferForm />
            </Layout>
          </PrivateRoute>
        }
      />

      {/* INVALID URL */}
      <Route
        path="*"
        element={
          <Navigate to="/" replace />
        }
      />

    </Routes>
  );
}

export default App;
